var _localizer = $.extend({}, default_product_Localization, window.productLocalization || {});

window.substringMatcher = function (strs) {
    return function findMatches(q, cb) {
        var matches, substringRegex;
        matches = [];
        substrRegex = new RegExp(q, 'i');
        $.each(strs, function (i, str) {
            if (substrRegex.test(str)) {
                matches.push(str);
            }
        });

        cb(matches);
    };
};

function autocomplete(itm) {
    $(itm).typeahead(t_settings, {
        name: 'Key-' + window.product.idx,
        limit: 10,
        source: substringMatcher(hints)
    });
}

var t_settings = {
    hint: false,
    highlight: true,
    classNames: {
        menu: "dropdown-menu suggestion-list",
        suggestion: "suggestion-item"
    }
};

var $showErorr = function $showErorr(errors) {
    $notification.error("<strong>" + errors[0].key + "</strong>", "<span>" + errors[0].value[0] + "</span>", 2000, "fa fa-exclamation-circle");
};

var $fail = function $fail(jqXHR, Status) {
    $notification.error(window.localization.success.error, jqXHR.statusText, 2000, "fa fa-exclamation-circle");
};

$(document).ready(function () {
    //-----------------------------------------------------------------
    //--- LoadHints ------------------------------------------
    //-----------------------------------------------------------------

    $.getJSON(window.productlinks.LoadHints, function (response) {
        hints = response.data;
        autocomplete('.typeahead');
    });

    //-----------------------------------------------------------------
    //--- Shipping  ------------------------------------------
    //-----------------------------------------------------------------
    $('#Shipping').on('change', function () {

        if ($(this).is(":checked")) {
            $('#IsFreeShipping').prop('disabled', false);
            $('.shipping_inputs input').each(function (indx, itm) {
                return $(itm).prop('disabled', false);
            });
        } else {
            $('#IsFreeShipping').prop('disabled', true).prop('checked', false);
            $('.shipping_inputs input').each(function (indx, itm) {
                return $(itm).prop('disabled', true).val(0);
            });
        }
    });
    //-----------------------------------------------------------------
    //--- select picker  ------------------------------------------
    //-----------------------------------------------------------------


    $('#publish_product').on('change', function (e) {
        var $this = $(this);
        var Published = $this.data("published-text") || "Published successfully";
        var Unpublished = $this.data("unpublished-text") || "Unpublished successfully";

        console.log(window.productlinks.publishProduct);
        $.get(window.productlinks.publishProduct).done(function (res) {
            if (res.success) {
                if ($this.is(":checked")) {
                    $notification.success("", Published, 2000, "fa fa-check");
                } else {
                    $notification.warning("", Unpublished, 2000, "fa fa-check");
                }
            }
        });
        fail(function (jqXHR, Status) {
            return $fail(jqXHR, Status);
        });
    });

    $(document).on('click', '.delete-product', function (e) {
        e.preventDefault();
        var $this = $(this);
        var dataUrl = $this.data("url");
        var backurl = $this.data("backurl");
        $Confirm({}, function (result) {
            if (result.value) {
                $.ajax({
                    url: dataUrl,
                    type: 'Get',
                    dataType: "json",
                    data: {
                        redirection: true
                    }
                }).done(function (data) {
                    if (data.success) {
                        $notification.success("", window.localization.deleted_successfully, 2000, "fa fa-check");
                        window.location.assign(backurl || window.location.origin + '/Admin/products');
                    } else {
                        $showErorr(data.errors);
                    }
                }).fail(function (jqXHR, Status) {
                    return $fail(jqXHR, Status);
                });
            }
        });
    });
}); // end document ready fn
$(document).ready(function () {

    //-----------------------------------------------------------------
    //--- specifications  ------------------------------------------
    //-----------------------------------------------------------------

    var specifications_template = "<div class=\"form-group clearfix inputitem\" id=\"sitem-##\">\n    <div class=\"col-md-3 col-sm-3 col-xs-12 scrollable-dropdown-menu\">\n        <input type=\"text\" id=\"Key-##\" name=\"Specifications[##].Key\" class=\"form-control typeahead\" value=\"\" required />\n    </div>\n    <div class=\"col-md-8 col-sm-7 col-xs-12\">\n        <textarea type=\"text\" id=\"Value-##\" name=\"Specifications[##].Value\" class=\"form-control\" rows=\"1\"></textarea>\n    </div>\n    <div class=\"col-md-1 col-sm-2 col-xs-12\">\n        <a class=\"btn btn-remove-content m-t0 remove-content\" data-id=\"##\">\n            <i class=\"fa fa-trash-o\"></i>\n        </a></div>\n</div>";

    $('#addItems').on('click', function (e) {
        e.preventDefault();
        var temp = specifications_template.replace(/##/g, window.product.idx);
        $('#s_wrapper').append(temp);
        autocomplete("#Key-" + window.product.idx);
        window.product.idx++;
    });

    $(document).on('click', '.remove-content', function (e) {
        e.preventDefault();
        if (window.product.idx > 0) {
            var id = $(this).data('id');

            $('#sitem-' + id).remove();
            $('.remove-content').addClass('disabled');
            var items = $('#s_wrapper').find('.inputitem');
            items.each(function (i, itm) {
                var item = $(itm);
                input = item.find('input[id^="Key-"]'), textarea = item.find('textarea[id^="Value-"]');
                item.attr('id', "sitem-" + i);
                input.attr("id", "Key-" + i).attr('name', "Specifications[" + i + "].Key");
                textarea.attr("id", "Value-" + i).attr('name', "Specifications[" + i + "].Value");
                item.find('.remove-content').attr('data-id', i);
            });
            $('.remove-content').removeClass('disabled');
            window.product.idx--;
        }
    });
    //-- end -- 
});
$(document).ready(function () {

    var imgTemplate = "<div class=\"col-md-3 col-sm-4 animated zoomIn duration-300\" >\n<figure class=\"imgbox imgnew\" id=\"preview-@@\">\n<a href=\"#\" class=\"remove-btn\" id=\"removeimage\"><i class=\"fa fa-times\"></i></a>\n<input type=\"checkbox\" class=\"ignore\" id=\"thumb-checkbox\" />\n<div class=\"thumbnail\">\n<img src=\"\" alt=\"\" id=\"imagePreview-@@\"  /></div><i  class=\"fa fa-upload\" ></i></figure></div>";
    //-----------------------------------------------------------------
    //--- Images  ------------------------------------------
    //-----------------------------------------------------------------


    var removeImages = function removeImages(ids, urls, callback) {

        $.ajax({
            url: window.productlinks.deleteimages,
            type: 'POST',
            dataType: "json",
            cache: false,
            data: { images: urls, ProductId: window.product.pid }
        }).done(function (data) {
            $notification.success(window.localization.success, "", 2000, "fa fa-check");
            if (callback && typeof callback == 'function') callback(ids, data);
        }).fail(function (jqXHR, Status) {
            return $fail(jqXHR, Status);
        });
    };
    // remove image

    $(document).on('click', '#removeimage', function () {
        var urls = [],
            ids = [];
        var $parent = $(this).parent();
        var id = $parent.attr('id');
        var $img = $parent.find('img');

        $Confirm({}, function (result) {

            if (result.value) {

                if (!$parent.hasClass('imgnew')) {
                    ids.push(id);
                    urls.push($img.attr('src'));

                    removeImages(ids, urls, function (itemsId, data) {
                        return $(".imgbox[id=\"" + id + "\"]").parent().remove();
                    });
                } else {
                    var _id = parseInt(id.split("-")[1]);
                    $parent.parent().remove();
                    $('#inputsfiles input[id="input-' + _id + '"]').remove();

                    if (_id < $index - 1) reorderItems();

                    $index--;
                }
            }
        });
    });

    var $index = 0;
    var thumbId = [];
    var oldimagesCount = 0;

    var reorderItems = function reorderItems() {
        $('.imgnew').each(function (index, item) {
            var $img = $(item).find('img');
            $(item).attr('id', 'preview-' + index);
            $img.attr('id', 'imagePreview-' + index);
        });
        $('#inputsfiles input').each(function (i, itm) {
            return $(itm).attr('id', "input-" + i).attr('name', "Files[" + i + "]");
        });
    };

    var removePreview = function removePreview(id) {

        $("#" + id).parent().remove();
        var it = parseInt(id.split('-')[1]);
        $('#inputsfiles').find("#input-" + it).remove();

        if (it < $index) {
            reorderItems();
        }

        $index--;
    };

    var removeServerImg = function removeServerImg(id, urls, ids) {

        ids.push(id);
        urls.push($('#img-' + id).attr('src'));

        if (urls.length == oldimagesCount) {
            removeImages(ids, urls, function (itemsId, data) {
                return $.each(ids, function (x, i) {
                    return $(".imgbox[id=\"" + i + "\"]").parent().remove();
                });
            });
        }
    };

    var removeSelected = function removeSelected() {
        var deferred = new $.Deferred();
        var urls = [],
            ids = [],
            indxs = 0;
        if (thumbId.length > 0) {

            $.each(thumbId, function (i, id) {
                if (isNaN(id)) {
                    removePreview(id);
                } else {
                    indxs++;
                    removeServerImg(id, urls, ids);
                }
                if (thumbId.length - 1 == i) deferred.resolve(true);
            });
        }
        return deferred.promise();
    };

    $('#removeImages').click(function () {

        $Confirm({}, function (result) {
            if (result.value) {
                removeSelected().then(function (status) {
                    thumbId = [];
                    oldimagesCount = 0;
                    $('#removeImages').addClass('hidden');
                });
            }
        });
    });

    //-------------------------------------------------------------------------
    //---- select images to be removed----------------------------------------- 
    //-------------------------------------------------------------------------
    $(document).on('change', 'input[id^="thumb-checkbox"]', function () {

        var $el = $(this);
        var id = $el.parent().attr('id');
        if ($el.is(":checked")) {
            thumbId.push(id);
            if (thumbId.length == 1) $('#removeImages').removeClass('hidden');
            if (!isNaN(id)) oldimagesCount++;
        } else {
            thumbId.splice(thumbId.indexOf(id), 1);
            if (thumbId.length <= 0) $('#removeImages').addClass('hidden');
            if (!isNaN(id)) oldimagesCount--;
        }
    });

    $(document).on('change', '#addImages', function () {
        var $el = $(this);
        $clone = $el.clone();
        if (this.files && this.files[0]) {
            $clone.attr('id', "input-" + $index).attr('name', "Files[" + $index + "]").removeClass();
            $clone.appendTo('#inputsfiles');
            var reader = new FileReader();
            reader.onload = function (e) {
                var temp = imgTemplate.replace(/@@/g, $index);
                $(temp).appendTo('.images-zone');
                $("#imagePreview-" + $index).attr('src', e.target.result);
                $index++;
            };
            reader.readAsDataURL(this.files[0]);
            $el.wrap('<form>').closest('form').get(0).reset();
            $el.unwrap();
        }
    });

    //-- end --
});
