$(document).ready(function () {

    //------------------------------------------------------------------
    //#region #1  attribute template & option template
    //------------------------------------------------------------------
    var attrTemplate = "\n<section id=\"attr_item-@@\">\n    <div class=\"clearfix inputitem\">\n        <div class=\"row attribute\">\n            <div class=\"col-md-4 col-sm-4 p-0\">\n                <div class=\"form-group clearfix\">\n                    <label for=\"Attribute-type-@@\" class=\"control-label col-md-3 col-sm-12 col-xs-12 \">" + _localizer.f_type + "</label>\n                    <div class=\"col-md-9 col-sm-12 col-xs-12 \">\n                        <input type=\"text\" name=\"Attributes[@@].type\" id=\"Attribute-type-@@\" class=\"form-control ignore\"\n                            disabled value=\"select\" />\n                        <span asp-validation-for=\"Attributes[@@].type\" class=\"text-danger invalid_field\"></span></div>\n                </div>\n            </div> \n            <div class=\"col-md-4 col-sm-4 p-0\">\n                <div class=\" form-group clearfix\">\n                    <label for=\"Attribute-name-@@\" class=\"control-label col-md-3 col-sm-12 col-xs-12 \">" + _localizer.f_name + "</label>\n                    <div class=\"col-md-9 col-sm-12 col-xs-12 \">\n                        <input type=\"text\" name=\"Attributes[@@].Name\" id=\"Attribute-name-@@\" data-value=\"\" class=\"form-control \" />\n                        <span asp-validation-for=\"Attributes[@@].Name\" class=\"text-danger invalid_field\"></span></div>\n                </div>\n            </div>\n            <div class=\"col-md-4 col-sm-4 col-xs-12 p-0\">\n                <div class=\"form-group clearfix text-right flip p-x-3\">\n                    <a class=\"btn btn-save-link save-attrbute\" data-id=\"@@\" data-new=\"true\">\n                        <i class=\"fa fa-check\" aria-hidden=\"true\"></i>" + _localizer.save + "</a>\n                    <a class=\"btn btn-remove-link remove-attrbute\" data-new=\"true\" data-id=\"@@\">\n                        <i class=\"fa fa-trash-o\"></i> " + _localizer.delete + "</a>\n                </div>\n            </div>\n        </div>\n        <div class=\"attr_values collapse\" id=\"values-@@\">\n            <div class=\"options-box\" id=\"options-@@\">\n                <div class=\"form-group m-y-2 \" id=\"opt-@@-##\">\n                    <div class=\"clearfix\">\n                        <label for=\"Value-@@-##\" class=\"control-label col-md-2  col-xs-12 col-sm-4 m-y-2\">" + _localizer.option_value + "</label>\n                        <div class=\"col-md-3 col-xs-12 col-sm-8 m-y-2\">\n                            <input type=\"text\" name=\"Attributes[@@][Values][##][Value]\" class=\"form-control\" id=\"Value-@@-##\" /></div>\n                        <label for=\"Price -@@-##\" class=\"control-label col-md-2  col-xs-12 col-sm-4 m-y-2\">" + _localizer.f_price + "</label>\n                        <div class=\"col-md-3 col-xs-12 col-sm-8 m-y-2\">\n                            <input type=\"number\" name=\"Attributes[@@][Values][##][Price]\" class=\"form-control\" id=\"Price-@@-##\"\n                                min=\"0\" />\n                        </div>\n                        <div class=\"col-md-2 col-xs-12\">\n                            <a class=\"btn btn-remove-link  pull-right flip-dir m-y-2 remove-option\" data-id=\"opt-@@-##\"><i\n                                    class=\"fa fa-trash-o\"></i>" + _localizer.delete + "</a>\n                            <a class=\"btn btn-save-link save-option pull-right flip-dir m-y-2\" data-id=\"opt-@@-##\"\n                                data-new=\"true\">\n                                <i class=\"fa fa-check\" aria-hidden=\"true\"></i>" + _localizer.save + "</a>\n                        </div>\n                    </div>\n                    <hr class=\"line\" />\n                </div>\n            </div>\n            <div class=\"option-footer text-right flip\">\n                <a class=\"btn btn-addContent m-y-2 m-x-2 small\" id=\"addOptions\" data-attr=\"@@\"><i class=\"fa fa-plus\"></i>" + _localizer.add_option + "</a></div>\n        </div>\n    </div>   <hr class=\"m-t0 m-b5\" />\n</section>";
    var optTemplate = "<div class=\"form-group m-y-2 \" id=\"opt-@@-##\">\n        <div class=\" clearfix\">\n            <label for=\"Value-@@-##\" class=\"control-label col-md-2  col-xs-12 col-sm-4 m-y-2\">" + _localizer.option_value + "</label>\n            <div class=\"col-md-3 col-xs-12 col-sm-8 m-y-2\">\n                <input type=\"text\" name=\"Attributes[@@][Values][##][Value]\" class=\"form-control ignore\" id=\"Value-@@-##\" /></div>\n            <label for=\"Price-@@-##\" class=\"control-label col-md-2  col-xs-12 col-sm-4 m-y-2\">" + _localizer.f_price + "</label>\n            <div class=\"col-md-3 col-xs-12 col-sm-8 m-y-2\">\n                <input type=\"number\" name=\"Attributes[@@][Values][##][Price]\" class=\"form-control ignore\" id=\"Price-@@-##\"\n                    min=\"0\" value=\"0\" /></div>\n            <div class=\"col-md-2 col-xs-12\">\n                <a class=\"btn btn-remove-link  pull-right flip-dir m-y-2 remove-option\" data-new=\"true\" data-id=\"opt-@@-##\">\n                    <i class=\"fa fa-trash-o\"></i>" + _localizer.delete + "</a>\n                <a class=\"btn btn-save-link save-option pull-right flip-dir m-y-2\" data-id=\"opt-@@-##\" data-new=\"true\">\n                    <i class=\"fa fa-check\" aria-hidden=\"true\"></i>" + _localizer.save + "</a> </div>\n        </div><hr class=\"line\" />\n    </div>";
    //------------------------------------------------------------------
    //#endregion #1
    //------------------------------------------------------------------


    //------------------------------------------------------------------
    //#region #2   append attrubite template to dom  
    //------------------------------------------------------------------
    $('#addAttrbutes').on('click', function (e) {
        e.preventDefault();
        var temp = attrTemplate.replace(/@@/g, window.product.attrIdx).replace(/##/g, 0);
        $('#a_wrapper').append(temp);
        window.product.attrIdx++;
    });
    //------------------------------------------------------------------
    //#endregion #2
    //------------------------------------------------------------------


    //------------------------------------------------------------------
    //#region #3 toggle atrribute status to update
    //------------------------------------------------------------------
    var inputTempValue = {};
    $(document).on('click', '.update-attrbute', function (e) {
        e.preventDefault();
        $(this).hide();
        var id = $(this).data('id');
        var inputName = $("#Attribute-name-" + id);
        inputTempValue[id] = inputName.val();
        inputName.removeAttr('disabled');
        $(".save-attrbute[data-id=\"" + id + "\"]").removeClass('hidden');
    });
    //------------------------------------------------------------------
    //#endregion #3
    //------------------------------------------------------------------


    //------------------------------------------------------------------
    //#region #4 toggle attribute buttons and show error message
    //------------------------------------------------------------------
    var $toggleUpdateSaveButtons = function $toggleUpdateSaveButtons($this, inputName, id) {
        $this.addClass('hidden');
        $(".update-attrbute[data-id=\"" + id + "\"]").show();
        inputName.attr('disabled', 'disabled').removeClass('valid_field');
    };

    //insert case
    var $addUpdateButton = function $addUpdateButton($this, inputName, id) {

        inputName.attr('disabled', 'disabled').attr("data-value", inputName.val()).removeClass('valid_field');
        $('.remove-attrbute[data-id="' + id + '"]').removeAttr('data-new');
        $this.removeAttr('data-new').addClass('hidden');

        $this.before("<a class=\"btn  btn-link btn-values\" role=\"button\"  data-toggle=\"collapse\" \n    href=\"#values-" + id + "\" aria-expanded=\"false\" aria-controls=\"values-" + id + "\">\n    <i class=\"fa fa-cubes\" aria-hidden=\"true\"></i>" + _localizer.values + "</a>");

        $this.after("<a class=\"btn btn-update-link update-attrbute\" data-id=\"" + id + "\"> \n            <i class=\"fa fa-pencil-square-o\" aria-hidden=\"true\"></i>" + _localizer.edit + "</a>");

        $("#values-" + id).attr('data-attribute', inputName.val());
    };

    //------------------------------------------------------------------
    //#endregion #4
    //------------------------------------------------------------------


    //------------------------------------------------------------------
    //#region #5 save attribute
    //------------------------------------------------------------------
    $(document).on('click', '.save-attrbute', function (e) {
        e.preventDefault();

        var $this = $(this),
            isNew = $this[0].hasAttribute("data-new"),
            id = $this.data('id'),
            inputName = $('#Attribute-name-' + id);

        if (isNew) {

            if (inputName.val().length > 0) {
                var att_data = {
                    name: inputName.val(),
                    type: $('#Attribute-type-' + id).val(),
                    productid: window.product.pid
                };
                $.ajax({
                    url: window.productlinks.createAttributes,
                    type: 'POST',
                    dataType: "json",
                    data: att_data,
                    beforeSend: function beforeSend() {
                        return $this.find('i').removeClass().addClass('fa fa-spinner fa-pulse ');
                    },
                    complete: function complete() {
                        return $this.find('i').removeClass().addClass('fa fa-check');
                    }
                }).done(function (data) {
                    if (data.success) {
                        $addUpdateButton($this, inputName, id);
                        $notification.success(window.localization.success, "", 2000, "fa fa-check");
                    } else {
                        $showErorr(data.errors);
                    }
                }).fail(function (jqXHR, Status) {
                    return $fail(jqXHR, Status);
                });
            } else {
                inputName.addClass('invalid_field').removeClass('valid_field');
                inputName.on('change', function () {
                    return inputName.removeClass('invalid_field');
                });
            }
        } else {

            if (inputName.val() != inputTempValue[id]) {
                var attdata = {
                    originalName: inputTempValue[id],
                    name: inputName.val(),
                    type: $('#Attribute-type-' + id).val(),
                    productid: window.product.pid
                };
                $.ajax({
                    url: window.productlinks.editAttributes,
                    type: 'POST',
                    dataType: "json",
                    data: attdata,
                    beforeSend: function beforeSend() {
                        return $this.find('i').removeClass().addClass('fa fa-spinner fa-pulse ');
                    },
                    complete: function complete() {
                        return $this.find('i').removeClass().addClass('fa fa-check');
                    }
                }).done(function (data) {
                    if (data.success) {

                        $notification.success(window.localization.success, "", 2000, "fa fa-check");
                        $toggleUpdateSaveButtons($this, inputName, id);
                        $refreshCombinationsTable(data.result);
                    } else {
                        inputName.val(inputTempValue[id]);
                        $showErorr(data.errors);
                    }
                }).fail(function (jqXHR, Status) {
                    $fail(jqXHR, Status);
                    inputName.val(inputTempValue[id]);
                });
            } else {
                $this.find('i').removeClass().addClass('fa fa-check');
                $toggleUpdateSaveButtons($this, inputName, id);
            }
        }
    });

    //------------------------------------------------------------------
    //#endregion #5
    //------------------------------------------------------------------


    //------------------------------------------------------------------
    //#region #6 remove attributes
    //------------------------------------------------------------------
    var removeAttribute = function removeAttribute($this) {
        if (window.product.attrIdx >= 0) {
            var id = $this.data('id');
            $('#attr_item-' + id).remove();
        }
    };

    var deleteattribute = function deleteattribute($this) {

        $.ajax({
            url: window.productlinks.deleteattribute,
            type: 'Get',
            dataType: "json",
            data: {
                productid: window.product.pid,
                name: $this.parents('.attribute').find('input[id^="Attribute-name"]').data("value")
            }
        }).done(function (data) {
            if (data.success) {
                $notification.success(window.localization.success, "", 2000, "fa fa-check");
                removeAttribute($this);
            } else {
                $showErorr(data.errors);
            }
        }).fail(function (jqXHR, Status) {
            return $fail(jqXHR, Status);
        });
    };

    $(document).on('click', '.remove-attrbute', function (e) {
        e.preventDefault();
        var $this = $(this),
            isNew = $this[0].hasAttribute("data-new");

        if (isNew) removeAttribute($this);else $Confirm({}, function (result) {
            return result.value ? deleteattribute($this) : false;
        });
    });

    //------------------------------------------------------------------
    //#endregion #6
    //------------------------------------------------------------------


    //------------------------------------------------------------------
    //#region #7  `add  new attribute value`
    //------------------------------------------------------------------
    $(document).on('click', '#addOptions', function (e) {
        e.preventDefault();
        var id = $(this).data('attr');
        var count = $("#options-" + id).children('[id^="opt-"]').length;

        var temp = optTemplate.replace(/@@/g, id).replace(/##/g, count);
        $("#options-" + id).append(temp);
    });

    //------------------------------------------------------------------
    //#endregion #7
    //------------------------------------------------------------------
    /* 
    '<a class="btn btn-remove-link  pull-right m-y-2 remove-option" data-id="'+id+'">'+
            '<i class="fa fa-trash-o"></i> Delete </a>'+
    */

    //------------------------------------------------------------------
    //#region #8 save attribute value
    //------------------------------------------------------------------

    var $toggleSaveUpdateOption = function $toggleSaveUpdateOption($this, opt, id) {

        $(".Update-option[data-id=\"" + id + "\"]").show();

        $this.addClass('hidden');

        opt.find('input').attr('disabled', 'disabled');
    };

    var $addUpdateOptionBtn = function $addUpdateOptionBtn($this, opt, id) {
        $this.removeAttr('data-new').addClass('hidden');

        $this.siblings().removeAttr('data-new');

        var temp = "<a class=\"btn btn-update-link Update-option pull-right flip  m-y-2\" data-id=\"" + id + "\">\n                <i class=\"fa fa-pencil-square-o\" aria-hidden=\"true\"></i>" + _localizer.edit + "</a>";

        $this.after(temp);
        opt.find('input').removeClass('valid_field').attr('disabled', 'disabled');
    };

    var addNewOptionValue = function addNewOptionValue($this, opt, atrrname, id) {
        if (opt.find('input')[0].value.length > 0) {

            $.ajax({
                url: window.productlinks.createAttrValue,
                type: 'POST',
                dataType: "json",
                data: {
                    productid: window.product.pid,
                    value: opt.find('input')[0].value,
                    price: opt.find('input')[1].value,
                    attributename: atrrname
                },
                beforeSend: function beforeSend() {
                    return $this.find('i').removeClass().addClass('fa fa-spinner fa-pulse ');
                },
                complete: function complete() {
                    return $this.find('i').removeClass().addClass('fa fa-check');
                }
            }).done(function (data) {
                if (data.success) {
                    $addUpdateOptionBtn($this, opt, id);
                    $notification.success(window.localization.success, "", 2000, "fa fa-check");
                } else {
                    $showErorr(data.errors);
                }
            }).fail(function (jqXHR, Status) {
                return $fail(jqXHR, Status);
            });
        } else {

            $(opt.find('input')[0]).addClass('invalid_field').removeClass('valid_field').on('change', function () {
                $(this).removeClass('invalid_field');
            });
        }
        delete inputOptionTemp[id];
    };

    $(document).on('click', '.save-option', function (e) {
        e.preventDefault();
        var $this = $(this),
            id = $this.data('id'),
            opt = $($this.parents('.form-group')[0]),
            isNew = $this[0].hasAttribute("data-new"),
            atrrname = $this.parents('.inputitem').find('input[id^="Attribute-name-"]').val();

        if (isNew) addNewOptionValue($this, opt, atrrname, id);else updateOptionValue($this, opt, atrrname, id);
    });

    //------------------------------------------------------------------
    //#endregion #8
    //------------------------------------------------------------------


    //------------------------------------------------------------------
    //#region #9 update attribute value
    //------------------------------------------------------------------
    var inputOptionTemp = {};
    // update option 
    $(document).on('click', '.Update-option', function (e) {
        e.preventDefault();
        var id = $(this).data('id');
        var opt = $($(this).parents('.form-group')[0]);
        opt.find('input').removeAttr('disabled');
        $(this).hide();
        inputOptionTemp[id] = {
            val: opt.find('input')[0].value,
            price: opt.find('input')[1].value
        };

        $(".save-option[data-id=\"" + id + "\"]").removeClass('hidden');
    });

    function updateOptionValue($this, opt, atrrname, id) {
        if (opt.find('input')[0].value != inputOptionTemp[id]['val'] || opt.find('input')[1].value != inputOptionTemp[id]['price']) {

            $.ajax({
                url: window.productlinks.editAttrValue,
                type: 'POST',
                dataType: "json",
                data: {
                    productid: window.product.pid,
                    value: opt.find('input')[0].value,
                    price: opt.find('input')[1].value,
                    originalvalue: inputOptionTemp[id]['val'],
                    attributename: atrrname
                },
                beforeSend: function beforeSend() {
                    $this.find('i').removeClass().addClass('fa fa-spinner fa-pulse ');
                },
                complete: function complete() {
                    $this.find('i').removeClass().addClass('fa fa-check');
                }
            }).done(function (data) {
                if (data.success) {
                    $notification.success(window.localization.success, "", 2000, "fa fa-check");
                    $addUpdateOptionBtn($this, opt, id);
                    $refreshCombinationsTable(data.result);
                    delete inputOptionTemp[id];
                } else {
                    $showErorr(data.errors);
                }
            }).fail(function (jqXHR, Status) {
                $fail(jqXHR, Status);
                $notification.error(window.localization.error, jqXHR.statusText, 2000, "fa fa-exclamation-circle");
                opt.find('input')[0].value = inputOptionTemp[id]['val'];
                opt.find('input')[1].value = inputOptionTemp[id]['price'];
            });
        } else {
            $toggleSaveUpdateOption($this, opt, id);
        }
    }

    //------------------------------------------------------------------
    //#endregion #9
    //------------------------------------------------------------------


    //------------------------------------------------------------------
    //#region #10  remove attribute value
    //------------------------------------------------------------------

    var removeOptionRow = function removeOptionRow($this) {

        var data = $this.data('id').split('-').slice(1);
        var index = parseInt(data[data.length - 1]);
        var id = parseInt(data[0]);
        var count = $('#options-' + id).children('[id^="opt-"]').length - 1;
        var regex = /([a-zA-z]+)+(-\d+-)+(\d+)/g;
        if (count >= 0) {
            $('#opt-' + id + '-' + index).remove();

            if (index < count) {
                $("#options-" + id).children('[id^="opt-"]').each(function (i, option) {
                    var opt = $(option);
                    opt.attr('id', 'opt-' + id + '-' + i);
                    $(option).find('.remove-option').attr('data-id', 'opt-' + id + '-' + i);
                    var label = opt.find('label');
                    label.each(function (l, lab) {
                        $(lab).attr('for', $(lab).attr('for').replace(regex, '$1-' + id + '-' + i));
                    });
                    var inputs = opt.find('input');
                    inputs.each(function (c, input) {
                        var ipt = $(input);
                        var reg = /([a-zA-z]+\W)+(\d+)+([a-zA-z]+\W)+(\d+)+([a-zA-z]+\W)/g;
                        ipt.attr('name', ipt.attr('name').replace(reg, '$1' + id + '$3' + i + '$5'));
                    });
                });
            }
        }
    };

    deleteOptionValue = function deleteOptionValue($this) {

        var opt = $($this.parents('.form-group')[0]);

        $.ajax({
            url: window.productlinks.deleteAttrValue,
            type: 'GET',
            dataType: "json",
            data: {
                productid: window.product.pid,
                attributename: $this.parents('.inputitem').find('input[id^="Attribute-name-"]').val(),
                value: opt.find('input')[0].value
            }
        }).done(function (data) {
            if (data.success) {
                $notification.success(window.localization.success, "", 2000, "fa fa-check");
                removeOptionRow($this);
            } else {
                $showErorr(data.errors);
            }
        }).fail(function (jqXHR, Status) {
            return $fail(jqXHR, Status);
        });
    };

    $(document).on('click', '.remove-option', function (e) {
        e.preventDefault();
        var $this = $(this);
        isNew = $this[0].hasAttribute("data-new");

        if (isNew) removeOptionRow($this);else $Confirm({}, function (result) {
            return result.value ? deleteOptionValue($this) : false;
        });
    });
    //------------------------------------------------------------------
    //#endregion #10
    //------------------------------------------------------------------


    //-- end --
});

var i = window.product.dtab || 0;

var template = "<section id=\"section-&&\" class=\"m-b3 clearfix\">\n    <a class=\"btn btn-remove-content\" id=\"remove-content\" data-id=\"&&\">\n        <i class=\"fa fa-trash-o\"></i></a>\n    <div class=\"form-group\">\n        <Label for=\"Title-&&\" class=\"control-label col-md-3 col-sm-4 col-xs-12\">" + _localizer.f_title + "</Label>\n        <div class=\"col-md-7 col-sm-8 col-xs-12\" id=\"\">\n            <input type=\"text\" name=\"Description[&&].Key\" id=\"Title-&&\" class=\"form-control m-b2\" required />\n        </div>\n    </div>\n    <div class=\"form-group\">\n        <Label for=\"Description-&&\" class=\"control-label col-md-3 col-sm-4 col-xs-12 \">" + _localizer.f_description + "</Label>\n        <div class=\"col-md-7 col-sm-8 col-xs-12\" id=\"\">\n            <textarea rows=\"4\" class=\"form-control\" id=\"Description-&&\" name=\"Description[&&].Value\"></textarea>\n        </div>\n    </div>\n    <hr class=\"line\" />\n</section>";

$('#addContent').on('click', function (e) {
    e.preventDefault();
    var temp = template.replace(/&&/g, i); //.replace(/%%/g, i+1)
    $('#ContentItems').append(temp);
    i++;
});

$(document).on('click', '#remove-content', function () {
    if (i > 0) {
        var id = $(this).data('id');
        $("#section-" + id).remove();

        if (id < i - 1) {
            var sections = $('#ContentItems').find('section');
            sections.each(function (indx, section) {
                var sec = $(section),
                    link = sec.find("#remove-content"),
                    labTitle = sec.find('.control-label[for^="title-"]'),
                    labContent = sec.find('.control-label[for^="Description-"]'),
                    input = sec.find('input[id^="title-"]'),
                    textarea = sec.find('textarea[id^="Description-"]');

                sec.attr("id", "section-" + indx);
                link.attr("data-id", indx);
                labTitle.attr("for", "title-" + indx);
                labContent.attr("for", "Description-" + indx);
                input.attr("id", "title-" + indx).attr('name', "Description[" + indx + "].Key");
                textarea.attr("id", "Description-" + indx).attr('name', "Description[" + indx + "].Value");
            });
        }
        i--;
    }
});

//------------------------------------------------------------------
/*
#1 -    combination modal   [show , ajax:get , hide ]  
#2 -    create combination  model   [fn]
#3 -    append new combination to table  [fn]
#4 -    append Errors to commbination modal [fn]
#5 -    validate and save new Combintion  [validate , ajax:post]
#6 -    toggle update combination button [fn]
#7 -    save updated Combination [ ajax:post ]
#8 -    toggle Publish Combination button [fn]
#9 -    publish & unpublish combination [ajax:get]
#10 -   refresh Combinations table  
#11 -   delete combination
#12 -   
#13 -   
*/
//------------------------------------------------------------------

$(document).ready(function () {
    var _this = this;

    //------------------------------------------------------------------
    //#region #1    combination modal
    //------------------------------------------------------------------
    $('#combinationModal').on('show.bs.modal', function (e) {
        var button = $(e.relatedTarget);
        var productid = button.data('productid');
        var modal = $(this);
        var trTemplate = "";
        modal.find('#pro_sku').val($('input[id="SKU"]').val()) || window.product.PSKU;

        $.getJSON(window.productlinks.geteditAttributes, function (data) {

            if (data.success && data.result.length > 0) {

                modal.find('.atrributes_selects_box').html(" ");
                $.each(data.result, function (idx, attr) {
                    modal.find('.atrributes_selects_box').append("<div class=\"form-group clearfix\" id=\"selects_box\">\n                        <label class=\"control-label col-md-3 col-sm-4\">" + attr.name + "</label>\n                        <div class=\"col-md-9 col-sm-8 col-xs-12\">\n                        <select class=\"form-control\" name=\"attr-" + attr.name + "-" + idx + "\"><option value=\"null\">" + _localizer.select + "  " + attr.name + " </option></select></div></div>");
                    $.each(attr.values, function (i, opt) {
                        modal.find('select[name="attr-' + attr.name + '-' + idx + '"]').append("<option value=\"" + opt.value + "\"> " + opt.value + " </option>");
                    });
                });
            } else if (data.success && data.result.length == 0) {
                modal.find('#saveCombination').hide();
                modal.find('.atrributes_selects_box').html("<div class=\"alert alert-warning\">" + _localizer.product_havent_attributes + "</div>");
            } else {
                $notification.error(window.localization.error, window.localization.something_wrong, 2000, "fa fa-exclamation-circle");
            }
        }).fail(function (jqXHR, Status) {
            return $fail(jqXHR, Status);
        });
    });
    $('#combinationModal').on('hidden.bs.modal', function (e) {

        var modal = $(_this);
        modal.find('.atrributes_selects_box').html('<div class="lds-ripple"><div></div><div></div></div>');

        if ($('#combinationModal').find('.alert').length > 0) $('.alert').remove();
    });
    //------------------------------------------------------------------
    //#endregion #1
    //------------------------------------------------------------------

    //------------------------------------------------------------------
    //#region  #2  create combination  model
    //------------------------------------------------------------------
    var createObj = function createObj($form) {
        var inputs = $form.find('input').serializeArray();
        var selects = $form.find('select').serializeArray();
        var deferred = new $.Deferred();
        var combinationData = {
            Attributes: {},
            productid: window.product.pid,
            ProductSku: window.product.PSKU
        };

        $.each(inputs, function (i, item) {
            return combinationData[item.name] = item.value;
        });

        $.each(selects, function (i, select) {
            if (select.value != "null") combinationData.Attributes[select.name.split('-')[1]] = select.value;
            if (selects.length - 1 == i) deferred.resolve(combinationData);
        });
        return deferred.promise();
    };

    //------------------------------------------------------------------
    //endregion  #2
    //------------------------------------------------------------------

    //------------------------------------------------------------------
    //#region  #3   append new combination to table 
    //------------------------------------------------------------------

    var appendTableRow = function appendTableRow(row, key, refresh) {

        var attrHtml = "";
        if (refresh) attrHtml = key.replace(/,/g, "<br/>").replace(/:/g, " : ");else $.each(row.attributes, function (index, item) {
            return attrHtml += index + " : " + item + " <br />";
        });

        var temp = "<tr><td>" + attrHtml + "</td><td>\n                <input type=\"number\" step=\"1\" class=\"form-control m-y-1 ignore\" name=\"ProductAttributeCombinations[" + window.product.comb + "].Quantity\"   value=\"" + row.quantity + "\" disabled /></td><td>\n                <p class=\"form-control-static\">" + row.sku + "</p></td><td>\n                <input type=\"number\" step=\"any\" class=\"form-control m-y-1 ignore\" name=\"ProductAttributeCombinations[" + window.product.comb + "].Price\" value=\"" + row.price + "\" disabled /></td> \n                <td><input type=\"number\" step=\"any\" class=\"form-control m-y-1 ignore\" name=\"ProductAttributeCombinations[" + window.product.comb + "].DiscountPrice\" value=\"" + row.discountPrice + "\" disabled /></td> \n                <td class=\"text-center\" ><a data-sku=\"" + row.sku + "\"  data-key=\"" + key + "\" class=\"btn btn-link-pup toggle_comb_publish\">   <span class=\"unpublished\"> <i class=\"fa fa-eye-slash c-red\"></i> <small>" + _localizer.unpublished + "</small></span></a> </td> \n                <td><a href=\"#\" class=\"btn btn-update-link update-combination  hidden m-y-2 \" data-index=\"" + window.product.comb + "\">\n                <i class=\"fa fa-pencil-square-o\" aria-hidden=\"true\"></i>" + _localizer.edit + "</a>\n                <a title=\"" + _localizer.delete_combination + "\" data-sku=\"" + row.sku + "\" data-key=\"" + key + "\" data-id=\"" + window.product.comb + "\" class=\"btn btn-remove-combination c-red m-y-2 remove-combination\">\n                <i class=\"fa fa-trash-o\"></i>" + _localizer.delete + "</a>\n                <a class=\"btn btn-save-link save-combination hidden m-y-2\" data-index=\"" + window.product.comb + "\">\n                <i class=\"fa fa-check\" aria-hidden=\"true\"></i>" + _localizer.save + "</a></td></tr>";

        if (row.published) {
            temp = temp.replace(/unpublished/g, 'published');
            temp = temp.replace('fa-eye-slash c-red', 'fa-eye c-green');
        }

        if ($('.combinations-table').has('.empty_row ').length > 0) $('.combinations-table').find('.empty_row').remove();

        $('.combinations-table tbody').append(temp);
        window.product.comb++;
    };

    //------------------------------------------------------------------
    //endregion #3
    //------------------------------------------------------------------


    //------------------------------------------------------------------
    //#region  #4  append Errors to commbination modal 
    //------------------------------------------------------------------

    var appendError = function appendError(errors, $form) {
        var alertTemp = "<div class=\"alert alert-danger alert-dismissible fade in\" style=\"border-radius: 0;\" role=\"alert\">\n    <button type=\"button\" class=\"close\" data-dismiss=\"alert\" aria-label=\"Close\">\n    <span aria-hidden=\"true\">\xD7</span></button><ol id=\"errors_list\" class=\"m-b0\"></ol></div>";

        if ($('#combinationModal').find('.alert').length <= 0) $form.before(alertTemp);

        $.each(errors, function (key, value) {
            return $.each(value.value, function (k, v) {
                return $('#errors_list').append("<li>" + v + "</li>");
            });
        });
    };

    //------------------------------------------------------------------
    //#endregion #4
    //------------------------------------------------------------------

    //------------------------------------------------------------------
    //#region  #5   validate and save new Combintion  
    //------------------------------------------------------------------
    var cobinations_validator = $(" #product_cobinations ").validate({
        errorClass: "invalid_field",
        validClass: "valid_field",
        ignore: ".ignore",
        rules: {
            "discountprice": {
                lessThan: ["#combination_price", "price"]
            },
            "price": {
                greaterThan: ["#discount_price", "Discount Price"]
            }
        },
        submitHandler: function submitHandler(form) {
            var $form = $(form);
            createObj($form).then(function (result) {

                if ($('#combinationModal').find('.alert').length > 0) $('.alert').remove();

                $.ajax({
                    url: window.productlinks.createCombination,
                    type: 'POST',
                    dataType: "json",
                    data: result
                }).done(function (data) {
                    if (data.success) {

                        $notification.success(window.localization.success, "", 2000, "fa fa-check");
                        $("[data-dismiss=modal]").trigger({
                            type: "click"
                        });

                        appendTableRow(data.model, data.result.key);
                        $form[0].reset();
                    } else {
                        appendError(data.errors, $form);
                    }
                }).fail(function (jqXHR, Status) {
                    if (jqXHR.status == 400) {
                        appendError(jqXHR.responseJSON, $form);
                    } else {
                        $notification.error(window.localization.error, jqXHR.statusText, 2000, "fa fa-exclamation-circle");
                    }
                });
            });
            return false;
        }
    });
    $("#combination_price").on('keyup', function () {
        cobinations_validator.element("#discount_price");
    });
    $("#discount_price").on('keyup', function () {
        cobinations_validator.element("#combination_price");
    });

    //------------------------------------------------------------------
    //#endregion #5
    //------------------------------------------------------------------


    //------------------------------------------------------------------
    //#region #6  toggle update combination button 
    //------------------------------------------------------------------
    var ShowUpdateBtn = function ShowUpdateBtn($this, $tr) {
        $tr.find(":input").attr('disabled', 'disabled');
        $this.addClass('hidden');
        $this.siblings('.update-combination').removeClass('hidden');
    };

    var combinationTemp = {};
    $(document).on('click', '.update-combination', function (e) {
        e.preventDefault();
        var $tr = $($(this).parents('tr')[0]),
            index = $(this).data('index');
        $tr.find(":input").removeAttr('disabled');
        combinationTemp[index] = $tr.find(":input").serializeArray();
        $(this).addClass('hidden').siblings('a.save-combination').removeClass('hidden');
    });
    //------------------------------------------------------------------
    //#endregion #6
    //------------------------------------------------------------------


    //------------------------------------------------------------------
    //#region #7 save updated Combination
    //------------------------------------------------------------------
    $(document).on('click', '.save-combination', function () {
        var _this2 = this;

        var $tr = $($(this).parents('tr')[0]),
            index = $(this).data('index');
        data = $tr.find(":input").serializeArray();
        if (JSON.stringify(combinationTemp[index]) !== JSON.stringify(data)) {
            var comData = {
                Quantity: data[0].value,
                Sku: combinationTemp[index][1].value,
                newSku: data[1].value,
                price: data[2].value,
                productid: window.product.pid
            };
            $.ajax({
                url: window.productlinks.editCombination,
                type: 'POST',
                dataType: "json",
                data: comData
            }).done(function (data) {
                if (data.success) {
                    $notification.success(window.localization.success, "", 2000, "fa fa-check");
                    ShowUpdateBtn($(_this2), $tr);
                } else {
                    showErrorsMsg(data.data);
                }
            }).fail(function (jqXHR, Status) {
                $fail(jqXHR, Status);
                $.each(data, function (idx, item) {
                    return $("input[name=\"" + item.name + "\"]").val(combinationTemp[index][idx].value);
                });
            });
        } else {
            delete combinationTemp[index];
            ShowUpdateBtn($(this), $tr);
        }
    });
    //------------------------------------------------------------------
    //#endregion #7
    //------------------------------------------------------------------


    //------------------------------------------------------------------
    //#region #8  toggle Publish Combination button 
    //------------------------------------------------------------------
    var togglePublishCombBtn = function togglePublishCombBtn($this, status) {
        if (status) {
            if ($this.find('span').hasClass('unpublished')) {
                $this.find('span').removeClass('unpublished').addClass('published');
                $this.find('small').text(_localizer.published);
                $this.find('i').removeClass('fa fa-spinner fa-pulse').addClass('fa fa-eye c-green');
            } else {
                $this.find('span').removeClass('published').addClass('unpublished');
                $this.find('small').text(_localizer.unpublished);
                $this.find('i').removeClass('fa fa-spinner fa-pulse').addClass('fa fa-eye-slash c-red');
            }
        } else {
            if ($this.find('span').hasClass('unpublished')) $this.find('i').removeClass('fa fa-spinner fa-pulse').addClass('fa fa-eye-slash c-red');else $this.find('i').removeClass('fa fa-spinner fa-pulse').addClass('fa fa-eye c-green');
        }
    };
    //------------------------------------------------------------------
    //#endregion #8
    //------------------------------------------------------------------


    //------------------------------------------------------------------
    //#region #9 publish & unpublish combination
    //------------------------------------------------------------------
    $(document).on('click', '.toggle_comb_publish', function (e) {
        e.preventDefault();
        var $this = $(this);

        $this.find('i').removeClass().addClass("fa fa-spinner fa-pulse");

        $.ajax({
            url: window.productlinks.publishCombination,
            type: 'GET',
            dataType: "json",
            data: {
                productid: window.product.pid,
                combinationkey: $this.data('key'),
                sku: $this.data('sku')
            }
        }).done(function (data) {
            if (data.success) {
                togglePublishCombBtn($this, true);
            } else {
                $showErorr(data.errors);
                togglePublishCombBtn($this, false);
            }
        }).fail(function (jqXHR, Status) {
            $fail(jqXHR, Status);
            togglePublishCombBtn($this, false);
        });
    });

    //------------------------------------------------------------------
    //#endregion #9
    //------------------------------------------------------------------


    //------------------------------------------------------------------
    //#region #10  refresh Combinations table 
    //------------------------------------------------------------------
    window.$refreshCombinationsTable = function (newData) {
        $('.combinations-table').find('tbody').html(' ');
        window.product.comb = 0;
        $.each(newData, function (index, row) {
            return appendTableRow(row, row.attributesvalues, true);
        });
    };
    //------------------------------------------------------------------
    //#endregion #10
    //------------------------------------------------------------------


    //------------------------------------------------------------------
    //#region #11   delete combination
    //------------------------------------------------------------------

    var emptyRowTemp = "<tr class=\"empty_row\"><td colspan=\"7\">                                    \n    <div class='empty_table text-center'> \n    <i class='fa fa fa-exclamation-circle'></i>\n    <p>" + _localizer.no_data_table + "</p></div></td></tr>";

    $(document).on('click', '.remove-combination', function (e) {
        e.preventDefault();
        var $this = $(this);
        $Confirm({}, function (result) {
            return result.value ? deleteCombination($this) : null;
        });
    });

    var deleteCombination = function deleteCombination($this) {
        $.ajax({
            url: window.productlinks.deleteCombination,
            type: 'Get',
            dataType: "json",
            data: {
                productid: window.product.pid,
                combinationkey: $this.data('key'),
                sku: $this.data('sku')
            }
        }).done(function (data) {
            if (data.success) {

                $notification.success(window.localization.success, "", 2000, "fa fa-check");

                $this.parents('tr').remove();

                if ($('.combinations-table tbody tr').length == 0) $('.combinations-table tbody').append(emptyRowTemp);
            } else {

                $showErorr(data.errors);
            }
        }).fail(function (jqXHR, Status) {
            return $fail(jqXHR, Status);
        });
    };

    //------------------------------------------------------------------
    //#endregion #11
    //------------------------------------------------------------------

    //-- end --
});